const vm = require("vm");
// Node.js's vm from an npm package: scripts in this context and in contextified sandboxes,
// compileFunction, syntax errors. Prints what it found; the same package under Node.js prints the same.
module.exports = function run() {
  console.log("this context", vm.runInThisContext("1 + 2"), typeof vm.runInThisContext("globalThis.process"));
  vm.runInThisContext("var vmGlobal = 42");
  console.log("var leaks to global", globalThis.vmGlobal);
  const sandbox = { x: 2, out: [] };
  const ctx = vm.createContext(sandbox);
  console.log("isContext", vm.isContext(ctx), vm.isContext({}), ctx === sandbox);
  vm.runInContext("var y = x * 10; z = 'set'; out.push(typeof process, typeof Array, typeof x)", ctx);
  console.log("sandbox", sandbox.y, sandbox.z, JSON.stringify(sandbox.out));
  console.log("runInNewContext", vm.runInNewContext("a + b", { a: 1, b: 2 }));
  const script = new vm.Script("count += 1; count", { filename: "counter.js" });
  const c2 = vm.createContext({ count: 0 });
  script.runInContext(c2);
  console.log("script twice", script.runInContext(c2), c2.count);
  console.log("separate realm", vm.runInNewContext("[]") instanceof Array, Array.isArray(vm.runInNewContext("[1]")));
  try {
    new vm.Script("let let = 1", { filename: "bad.js" });
  } catch (e) {
    console.log("syntax", e.name);
  }
  try {
    vm.runInNewContext("throw new TypeError('inside')");
  } catch (e) {
    console.log("thrown", e.name, e.message);
  }
  const fn = vm.compileFunction("return a + b + (typeof c)", ["a", "b"]);
  console.log("compileFunction", fn(1, 2));
  const withExt = vm.compileFunction("return ext + 1", [], { contextExtensions: [{ ext: 41 }] });
  console.log("contextExtensions", withExt());
  const inCtx = vm.compileFunction("return x", [], { parsingContext: vm.createContext({ x: "from context" }) });
  console.log("parsingContext", inCtx());
  console.log("keys", Object.keys(vm.runInNewContext("this", { p: 1, q: 2 })).join(","));
};
